{"name": "string_operations", "type": "code/c", "content": "#include <stdio.h>

// Function to compare two strings
int compareStrings(char str1[], char str2[]) {
    int i = 0;
    while (str1[i] != '\0' && str2[i] != '\0') {
        if (str1[i] != str2[i]) {
            return 0; // Strings are not equal
        }
        i++;
    }
    return (str1[i] == '\0' && str2[i] == '\0'); // Check if both ended
}

// Function to find length of string
int stringLength(char str[]) {
    int length = 0;
    while (str[length] != '\0') {
        length++;
    }
    return length;
}

// Function to find the longer string
void findLongerString(char str1[], char str2[]) {
    int len1 = stringLength(str1);
    int len2 = stringLength(str2);
    if (len1 > len2) {
        printf("Longer string: %s\n", str1);
    } else if (len2 > len1) {
        printf("Longer string: %s\n", str2);
    } else {
        printf("Both strings are of equal length.\n");
    }
}

// Function to concatenate two strings
void concatenateStrings(char str1[], char str2[], char result[]) {
    int i = 0, j = 0;
    while (str1[i] != '\0') {
        result[i] = str1[i];
        i++;
    }
    while (str2[j] != '\0') {
        result[i] = str2[j];
        i++;
        j++;
    }
    result[i] = '\0';
}

// Function to check if str2 is a substring of str1
int isSubstring(char str1[], char str2[]) {
    int i, j;
    for (i = 0; str1[i] != '\0'; i++) {
        for (j = 0; str2[j] != '\0'; j++) {
            if (str1[i + j] != str2[j]) {
                break;
            }
        }
        if (str2[j] == '\0') {
            return 1; // Found
        }
    }
    return 0; // Not found
}

int main() {
    char str1[100], str2[100], concatenated[200];

    printf("Enter first string: ");
    gets(str1);
    printf("Enter second string: ");
    gets(str2);

    // Compare strings
    if (compareStrings(str1, str2)) {
        printf("Strings are equal.\n");
    } else {
        printf("Strings are not equal.\n");
    }

    // Find longer string
    findLongerString(str1, str2);

    // Concatenate strings
    concatenateStrings(str1, str2, concatenated);
    printf("Concatenated string: %s\n", concatenated);

    // Check substring occurrence
    if (isSubstring(str1, str2)) {
        printf("'%s' is a substring of '%s'.\n", str2, str1);
    } else {
        printf("'%s' is not a substring of '%s'.\n", str2, str1);
    }

    return 0;
}"}

